{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — A focused intensive for your next 30 days</title>
  <meta name="description" content="A compact, outcome-driven approach to steadier habits and clearer priorities. Customized methods for how you feel today.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="site">
  <header class="site-header">
    <div class="brand">
      <svg class="logo" width="42" height="42" viewBox="0 0 42 42" aria-hidden="true"><rect rx="8" width="42" height="42" fill="#2b2b2b"></rect><path d="M10 30 L21 12 L32 30" stroke="#fff" stroke-width="2" fill="none"></path></svg>
      <div class="brand-text">
        <div class="name">{{BUSINESS_NAME}}</div>
        <div class="sub">A focused intensive in outcomes & habits</div>
      </div>
    </div>
    <nav class="main-nav" aria-label="Primary">
      <a href="index.html">Begin</a>
      <a href="about.html">Approach</a>
      <a href="services.html">Toolkit</a>
      <a href="programs.html">Programs</a>
      <a href="pricing.html">Investment</a>
      <a href="testimonials.html">Stories</a>
      <a href="book.html" class="cta">Book</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main>
    <!-- HERO: immediate action + mood selector -->
    <section class="hero" id="hero">
      <div class="pattern-wrap" aria-hidden="true">
        <img src="assets/img/pattern.svg" alt=""/>
      </div>
      <div class="hero-inner">
        <h1 class="headline">Find the right method for how you feel now.</h1>
        <p class="lead">Short, ritual-led intensives that transform the next 30 days. Choose your current state and we surface a tailored path with a clear next step.</p>

        <div class="controls">
          <label for="moodSelect">How are you today?</label>
          <select id="moodSelect" aria-label="Mood to method selector">
            <option value="scattered">Scattered & juggling too much</option>
            <option value="fatigued">Fatigued, low energy</option>
            <option value="stuck">Stuck, lacking progress</option>
            <option value="overcommitted">Overcommitted, too many priorities</option>
            <option value="steady">Steady — want momentum</option>
          </select>

          <div class="method" id="methodCard" aria-live="polite">
            <div class="method-title">Method</div>
            <div class="method-name" id="methodName">Micro-Rituals</div>
            <div class="method-desc" id="methodDesc">Tiny start-end rituals to anchor scattered days into coherent blocks.</div>
          </div>

          <div class="cta-group">
            <a id="primaryCta" class="primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <button id="previewPlan" class="secondary">Preview 30‑day map</button>
          </div>
        </div>
      </div>
    </section>

    <!-- OFFERS (different order) -->
    <section class="offers" id="offers">
      <h2>Offerings shaped around outcomes</h2>
      <div class="cards">
        <article class="card">
          <h3>Focus Sprint — 4 week intensive</h3>
          <p>One primary outcome, daily micro-practices, weekly alignment calls. For leaders who want measurable focus.</p>
          <div class="meta">Includes: Habit map, accountability check-ins, 2 coaching sessions</div>
          <div class="price">From $1,200</div>
        </article>

        <article class="card">
          <h3>Reset Intensive — 2 week recalibration</h3>
          <p>Bite-sized routines designed to restore baseline energy and clear cognitive clutter.</p>
          <div class="meta">Includes: Reset protocol, 1 deep session, daily prompts</div>
          <div class="price">From $650</div>
        </article>

        <article class="card">
          <h3>Anchor Framework — 6 week architecture</h3>
          <p>A framework to anchor time, decision rules, and weekly rhythms for dependable performance.</p>
          <div class="meta">Includes: Framework kit, weekly coaching, personal adaptations</div>
          <div class="price">From $2,400</div>
        </article>
      </div>
    </section>

    <!-- FRAMEWORK with progress meter -->
    <section class="framework" id="framework">
      <h2>The path map: 30 days, revealed</h2>
      <p>Select the outcomes you want and watch the map form — weekly focuses, milestone rituals, and the recommended first call to action.</p>

      <form id="goalsForm" class="goals">
        <label><input type="checkbox" name="goal" value="sleep"> Improve sleep consistency</label>
        <label><input type="checkbox" name="goal" value="energy"> Stabilize daily energy</label>
        <label><input type="checkbox" name="goal" value="focus"> Increase focused work blocks</label>
        <label><input type="checkbox" name="goal" value="boundaries"> Clearer boundaries around time</label>
        <label><input type="checkbox" name="goal" value="momentum"> Build momentum & measurable wins</label>
      </form>

      <div class="path-area">
        <div id="pathSummary" class="path-summary">No goals selected. Choose up to 3 to preview a path.</div>
        <div id="pathMap" class="path-map" aria-hidden="false"></div>
        <div id="pathAdvice" class="path-advice"></div>
      </div>
    </section>

    <!-- STORY -->
    <section class="story" id="story">
      <h2>Why this works</h2>
      <p>We stitch outcomes, daily cues, and weekly architecture. No medical claims — only habit design, accountability, and clear frameworks that support repeatable actions.</p>
      <ul>
        <li>Outcomes-first planning</li>
        <li>Micro-habits that compound</li>
        <li>Weekly rituals to redirect momentum</li>
      </ul>
    </section>

    <!-- PRICING PREVIEW -->
    <section class="pricing" id="pricing">
      <h2>Investment tiers</h2>
      <div class="tiers">
        <div class="tier">
          <h3>Starter Intensive</h3>
          <p>2 weeks — clarity, quick wins, simple rituals.</p>
          <div class="price">$650</div>
        </div>
        <div class="tier">
          <h3>Momentum Plan</h3>
          <p>4 weeks — built for outcome momentum and habit consolidation.</p>
          <div class="price">$1,200</div>
        </div>
        <div class="tier">
          <h3>Architecture Package</h3>
          <p>6 weeks — complete framework, team options, follow-up playbook.</p>
          <div class="price">$2,400</div>
        </div>
      </div>
      <p class="note">Tailored plans and installment options available. Pricing framed around outcomes, not hours.</p>
    </section>

    <!-- TESTIMONIALS -->
    <section class="testimonials" id="testimonials">
      <h2>Stories from past intensives</h2>
      <blockquote>
        "A practical map and short weekly commitments — real progress in three weeks."<cite>— M., manager</cite>
      </blockquote>
      <blockquote>
        "Clear rituals that actually stuck; I could feel momentum again."<cite>— S., entrepreneur</cite>
      </blockquote>
    </section>

    <!-- CTA -->
    <section class="final-cta" id="finalCta">
      <h2>Ready to choose your next step?</h2>
      <p>Pick a method, preview your 30-day map, then book a short orientation to begin.</p>
      <a id="finalPrimary" class="primary large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
    </section>

  </main>

  <footer class="site-footer">
    <div class="contact">
      <div>{{BUSINESS_NAME}}</div>
      <div>{{CITY}}, {{STATE}}</div>
      <div><a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
    </div>
    <small>© <span id="year"></span> {{BUSINESS_NAME}}</small>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
