{"path":"assets/css/styles.css","content":"/* Bold playful layout, mystic modern tone */
:root{
  --bg:#0f1720;--card:#111827;--muted:#94a3b8;--accent:#ff7aa2;--accent-2:#6de0ff;--glass:rgba(255,255,255,0.04);
  --radius:12px;--gap:18px;--maxW:1100px;--brand:#f8fafc;
}
*{box-sizing:border-box}
html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;font-size:16px;color:var(--brand);background:linear-gradient(180deg,#071018 0%, #071824 60%);}
.site{min-height:100%;display:flex;flex-direction:column}
.site-header{display:flex;justify-content:space-between;align-items:center;padding:18px;max-width:var(--maxW);margin:0 auto;width:calc(100% - 36px)}
.brand{display:flex;gap:12px;align-items:center}
.brand .logo{filter:drop-shadow(0 4px 10px rgba(0,0,0,0.6))}
.brand-text .name{font-weight:700}
.brand-text .sub{font-size:12px;color:var(--muted)}
.main-nav a{color:var(--muted);margin-left:14px;text-decoration:none;padding:8px 10px;border-radius:8px}
.main-nav a.cta{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#071021}
.main-nav a:hover{color:var(--brand)}

main{flex:1;max-width:var(--maxW);margin:18px auto;padding:0 18px}
section{margin:28px 0;padding:22px;background:transparent;border-radius:var(--radius)}
.hero{display:grid;grid-template-columns:1fr;position:relative;padding:30px;overflow:hidden}
.pattern-wrap{position:absolute;right:-80px;top:-60px;opacity:0.18;transform:rotate(8deg)}
.headline{font-size:28px;margin:0 0 8px}
.lead{color:var(--muted);max-width:60ch}
.controls{display:grid;grid-template-columns:1fr;gap:12px;max-width:700px;margin-top:12px}
.controls label{color:var(--muted)}
select{padding:10px;border-radius:10px;background:var(--glass);border:1px solid rgba(255,255,255,0.04);color:var(--brand)}
.method{background:rgba(255,255,255,0.02);padding:12px;border-radius:10px}
.method-title{font-size:12px;color:var(--muted)}
.method-name{font-weight:700}
.cta-group{display:flex;gap:10px;margin-top:8px}
.primary{background:linear-gradient(90deg,var(--accent),#ffb0d0);padding:10px 14px;border-radius:10px;color:#071021;text-decoration:none;font-weight:700}
.secondary{background:none;border:1px solid rgba(255,255,255,0.06);color:var(--muted);padding:8px 12px;border-radius:10px}

.offers .cards{display:flex;gap:14px;flex-wrap:wrap}
.card{background:linear-gradient(180deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));padding:16px;border-radius:12px;flex:1;min-width:220px}
.card h3{margin-top:0}
.card .price{margin-top:10px;font-weight:700;color:var(--accent)}

.framework .goals{display:flex;flex-wrap:wrap;gap:10px;margin-bottom:12px}
.goals label{background:var(--glass);padding:8px 12px;border-radius:10px;color:var(--brand)}
.path-area{background:rgba(255,255,255,0.02);padding:12px;border-radius:10px}
.path-summary{color:var(--muted);margin-bottom:8px}
.path-map{height:80px;display:flex;align-items:center;gap:6px}
.path-map .day{height:36px;width:26px;border-radius:6px;background:rgba(255,255,255,0.03);display:flex;align-items:center;justify-content:center;font-size:10px;color:rgba(255,255,255,0.6)}
.path-advice{margin-top:10px;color:var(--muted)}

.story ul{color:var(--muted)}
.pricing .tiers{display:flex;gap:12px}
.tier{background:rgba(255,255,255,0.02);padding:12px;border-radius:10px}
.tier .price{color:var(--accent);font-weight:700}
.testimonials blockquote{background:rgba(255,255,255,0.02);padding:12px;border-left:3px solid var(--accent);border-radius:6px}
.final-cta{display:flex;flex-direction:column;gap:12px;align-items:flex-start}
.final-cta .large{padding:14px 18px;font-size:18px}

.site-footer{margin-top:24px;padding:18px;background:transparent;border-top:1px solid rgba(255,255,255,0.03);display:flex;justify-content:space-between;max-width:var(--maxW);margin-left:auto;margin-right:auto}
.site-footer a{color:var(--muted)}

/* Responsive */
@media(min-width:900px){
  .hero{grid-template-columns:1fr 360px}
  .pattern-wrap{right:-20px;top:-80px}
  .controls{grid-column:1/-1}
}

/* playful interactions */
.primary:active{transform:translateY(1px)}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Utility
  function $(sel){return document.querySelector(sel)}
  function $all(sel){return Array.from(document.querySelectorAll(sel))}

  // DOM refs
  var moodSelect = $('#moodSelect');
  var methodName = $('#methodName');
  var methodDesc = $('#methodDesc');
  var primaryCta = $('#primaryCta');
  var previewBtn = $('#previewPlan');
  var goalsForm = $('#goalsForm');
  var pathMap = $('#pathMap');
  var pathSummary = $('#pathSummary');
  var pathAdvice = $('#pathAdvice');
  var finalPrimary = $('#finalPrimary');

  // Methods mapped to moods
  var methods = {
    scattered: {name:'Micro-Rituals', desc:'Short cues and end-of-block rituals to reclaim fragmented attention.', cta:'Start Micro‑Rituals'},
    fatigued: {name:'Energy Reset', desc:'Gentle, repeatable energy cues and rhythm adjustments to stabilize days.', cta:'Begin Energy Reset'},
    stuck: {name:'Momentum Sprint', desc:'A focused rhythm for measurable wins and weekly momentum.', cta:'Launch Momentum Sprint'},
    overcommitted: {name:'Boundary Protocol', desc:'Decision rules and simple boundaries to protect high-value time.', cta:'Adopt Protocol'},
    steady: {name:'Scaling Plan', desc:'Accelerate momentum with layered rituals and accountability nodes.', cta:'Scale Momentum'}
  };

  // Initial population
  function setMethodForMood(key){
    var m = methods[key] || methods.steady;
    methodName.textContent = m.name;
    methodDesc.textContent = m.desc;
    // update CTA text (keeps original href)
    primaryCta.textContent = m.cta + ' — ' + primaryCta.textContent.split('—').pop().trim();
    finalPrimary.textContent = m.cta;
  }
  setMethodForMood(moodSelect.value);

  moodSelect.addEventListener('change', function(e){
    setMethodForMood(e.target.value);
  });

  // Progress meter: create 30-day path map based on selected goals
  var goalColors = {
    sleep:'#8fbaf1',energy:'#ffd97a',focus:'#ffb3a7',boundaries:'#c9a7ff',momentum:'#7ee6b8'
  };

  function readGoals(){
    return $all('#goalsForm input[name="goal"]:checked').map(function(el){return el.value}).slice(0,3);
  }

  function renderPath(days, goals){
    // Clear
    pathMap.innerHTML = '';
    if(goals.length===0){
      pathSummary.textContent = 'No goals selected. Choose up to 3 to preview a path.';
      pathAdvice.textContent = '';
      return;
    }
    pathSummary.textContent = 'Preview: ' + goals.join(', ');

    // Distribute goal emphasis across 30 days in bands
    var bandSize = Math.max(5, Math.floor(days / Math.max(1, goals.length)));
    var dayItems = [];
    for(var d=1; d<=days; d++){
      var idx = Math.floor((d-1)/bandSize) % goals.length;
      // rhythmic boost on Sundays (every 7th day)
      var isMilestone = (d%7===0);
      var color = goalColors[goals[idx]] || '#ffffff';
      var el = document.createElement('div');
      el.className='day';
      el.dataset.day = d;
      el.style.background = isMilestone ? 'linear-gradient(180deg,#111 0%,'+color+'40 100%)' : color;
      el.title = 'Day '+d+' — focus: '+goals[idx];
      el.textContent = d%5===0?d:''; // sparse labels
      pathMap.appendChild(el);
      dayItems.push(el);
    }

    // Compose advice: weekly focuses
    var weeks = Math.ceil(days/7);
    var adviceLines = [];
    for(var w=0; w<weeks; w++){
      var start = w*7+1; var end = Math.min(days,(w+1)*7);
      var goalIndex = w % goals.length;
      adviceLines.push('Week '+(w+1)+': Day '+start+'–'+end+' — focus: '+goals[goalIndex]+'.');
    }
    pathAdvice.innerHTML = '<strong>Weekly focuses:</strong><br>'+adviceLines.join('<br>');

    // Small interactive detail: clicking a day highlights a suggest action
    pathMap.addEventListener('click', function(ev){
      var target = ev.target.closest('.day');
      if(!target) return;
      var d = +target.dataset.day;
      var goalForDay = target.title.split(' — ')[1];
      alert('Day '+d+': a focused action to support '+goalForDay+'.\nSuggested quick ritual: 5–10 minute anchor you can repeat.');
    });
  }

  // Hook up form changes
  goalsForm.addEventListener('change', function(){
    var goals = readGoals();
    // limit selection to 3 visually
    $all('#goalsForm input[name="goal"]').forEach(function(el){
      if(goals.length>=3 && !el.checked) el.disabled = true; else el.disabled = false;
    });
    renderPath(30, goals);
  });

  // Preview button toggles default suggestions
  previewBtn.addEventListener('click', function(){
    var goals = readGoals();
    if(goals.length===0){
      // pick defaults based on mood
      var mood = moodSelect.value;
      if(mood==='scattered') goals = ['focus','boundaries'];
      else if(mood==='fatigued') goals = ['sleep','energy'];
      else if(mood==='stuck') goals = ['momentum','focus'];
      else goals = ['momentum','boundaries'];
    }
    renderPath(30, goals);
    // Smooth scroll to map
    pathMap.scrollIntoView({behavior:'smooth',block:'center'});
  });

  // Set current year
  document.getElementById('year').textContent = new Date().getFullYear();

  // Accessibility: enable keyboard for day click by enter
  pathMap.addEventListener('keydown', function(e){
    if(e.key==='Enter' && e.target.classList.contains('day')) e.target.click();
  });

  // Initialize a tiny default map for steady mood
  renderPath(30, ['momentum','focus']);
})();"} 
